  (* [comment removed for export] *)
  Definition HDR (A cap : Z) (DATA : list byte) (cw Lc cfg sc : Z) : Prop :=
    6 + Lc <= Z.of_nat (length DATA) /\ Z.of_nat (length DATA) <= cap /\ cap <= MAX_INPUT /\ ablock_range A cap
